function command(id, executable, args) {
  if (process.platform === "win32" && (executable === "corepack" || executable.endsWith(".bat"))) {
    return { id, command: "cmd.exe", args: ["/d", "/s", "/c", executable, ...args] };
  }
  return { id, command: executable, args };
}

function runVersion(executable, args) {
  const invocation = command("version", executable, args);
  const result = spawnSync(invocation.command, invocation.args, { cwd: root, encoding: "utf8" });
  if (result.status !== 0) throw result.error ?? new Error(`${executable} version command failed`);
  return `${result.stdout ?? ""}${result.stderr ?? ""}`;
}
